package io.github.leetcode.tree;

import io.github.leetcode.tree.TreeNodes.TreeNode;

public class PathSumIII {

    public int pathSum(TreeNode root, int targetSum) {
        if (root == null) return 0;
        return getPaths(root, targetSum) + pathSum(root.left, targetSum) + pathSum(root.right, targetSum);
    }

    public int getPaths(TreeNode root, int targetSum) {
        if (root == null) return 0;

        return (root.val == targetSum ? 1 : 0) +
                getPaths(root.left, targetSum - root.val) + getPaths(root.right, targetSum - root.val);
    }

}

// Source : https://leetcode.com/problems/path-sum-iii/
// Author : Kris
// Date   : 2020-12-16

/***************************************************************************************************** 
 *
 * You are given a binary tree in which each node contains an integer value.
 * 
 * Find the number of paths that sum to a given value.
 * 
 * The path does not need to start or end at the root or a leaf, but it must go downwards
 * (traveling only from parent nodes to child nodes).
 * 
 * The tree has no more than 1,000 nodes and the values are in the range -1,000,000 to 1,000,000.
 * 
 * Example:
 * 
 * root = [10,5,-3,3,2,null,11,3,-2,null,1], sum = 8
 * 
 *       10
 *      /  \
 *     5   -3
 *    / \    \
 *   3   2   11
 *  / \   \
 * 3  -2   1
 * 
 * Return 3. The paths that sum to 8 are:
 * 
 * 1.  5 -> 3
 * 2.  5 -> 2 -> 1
 * 3. -3 -> 11
 * 
 ******************************************************************************************************/

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    // bruce force: O(n^2)
    public int pathSum(TreeNode root, int sum) {
        if (root == null) {
            return 0;
        }

        return helper(root, sum) + pathSum(root.left, sum) + pathSum(root.right, sum);
    }

    // 必须包含当前点
    int helper(TreeNode root, int sum) {
        if (root == null) {
            return 0;
        }

        var result = sum == root.val ? 1 : 0;
        result += helper(root.left, sum - root.val) + helper(root.right, sum - root.val);

        return result;
    }
}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
private:
    void solve(TreeNode* root, int targetSum, int &count, vector<int> path){

        if(!root)
            return;

        path.push_back(root -> val);
        int n = path.size();
        long int sum = 0;

        for(auto i = n - 1; i >= 0; i--){

            sum += path[i];
            if(sum == targetSum)
                count++;

        }

        solve(root -> left, targetSum, count, path);
        solve(root -> right, targetSum, count, path);

        path.pop_back();

    }

public:
    int pathSum(TreeNode* root, int targetSum) {

        int count = 0;
        vector<int> path;
        solve(root, targetSum, count, path);

        return count;
    }
};

